// For each churned customer, check if an exit_interview contact OR an
// existing maya 'Exit interview' task exists. If neither — emit the row
// so the next nodes create the task.
const rows = $input.first().json;
const out = [];
for (const c of (Array.isArray(rows) ? rows : [])) {
  // Check existing exit_interview contact.
  const cRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/customer_contacts?customer_id=eq.${c.id}&reason=eq.exit_interview&select=id&limit=1`,
    headers: { apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}` },
    json: true,
  });
  if (Array.isArray(cRes) && cRes.length > 0) continue;
  // Check existing task.
  const tRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/tasks?agent=eq.maya&title=ilike.${encodeURIComponent('Exit interview:%' + (c.full_name || c.email || '') + '%')}&status=neq.done&select=id&limit=1`,
    headers: { apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}` },
    json: true,
  });
  if (Array.isArray(tRes) && tRes.length > 0) continue;
  out.push({ json: c });
}
return out;
